import {flagArt} from './colour-flags.js';
// The manual specifies names and SF codes, not RGB. These are display interpretations.
export const displayPalette={SF01:'#c9cdd5',SF03:'#c49a42',SF10:'#c92329',SF13:'#ba641f',SF17:'#354fa0',SF20:'#142c50',SF25:'#c5a589',SF26:'#612c78',SF32:'#202124'};
const names={SF01:'Silver',SF03:'Gold',SF10:'Red',SF13:'Tenne',SF17:'Ultramarine',SF20:'Midnight',SF25:'Nude hosiery',SF26:'Purple',SF32:'Black'};
const divisions={command:{name:'Command',code:'SF13'},sciences:{name:'Sciences',code:'SF17'},engineering:{name:'Engineering / support',code:'SF10'}};
const ranks={ensign:[],lieutenant:[1],'lieutenant-commander':[1,0],commander:[1,1],captain:[1,0,1],commodore:[1,1,1],admiral:[1,1,1,1]};
const titleCase=s=>s.split('-').map(w=>w[0].toUpperCase()+w.slice(1)).join(' ');
export const plates=[
 {id:'ufp-banner',kind:'banner',category:'flags',title:'United Federation banner',sub:'Thirteen stars. One Federation.',page:35,to:'00:02:00',codes:['SF10','SF01'],note:'The white field in the drawing is specified red; the stars and elongated UFP monogram are silver. This is the manual’s tall, thirteen-star swallowtail design.'},
 {id:'ufp-seal',kind:'seal',category:'flags',title:'United Federation seal',sub:'The historic celestial seal.',page:36,to:'00:02:01',codes:['SF20','SF01'],note:'The circular celestial chart, wreath and UFP lettering are silver on a blue ground. The sheet calls SF20UC “Blue”; the colour table names the same code “Midnight”.'},
 {id:'alpha-centauri',kind:'centauri',category:'flags',title:'Alpha Centauri pennant',sub:'Gold on a purple field.',page:45,to:'00:02:10',codes:['SF26','SF03'],note:'A sword-bearing centaur, surrounding discs and stars, and the pennant border are specified gold. The ground is purple. Fine contours are reconstructed from the printed drawing.'},
 ...Object.entries(divisions).map(([id,d])=>({id:`${id}-badge`,kind:'badge',division:id,category:'insignia',title:`${d.name} insignia`,sub:'Gold ground / black device.',page:65,to:'01:03:00',codes:['SF03','SF32'],note:'All three division badges share a gold ground and black outline. Division is identified by the central device, not by changing the badge colour. The asymmetric delta follows the manual silhouette.'})),
 {id:'male-duty',kind:'uniform',category:'uniforms',title:'Duty uniform / male',sub:'Division colours and cuff braid.',page:66,to:'01:03:10',codes:['SF13','SF32','SF03'],note:'Long-sleeved duty tunic, black neckband, service trousers and boots. The source figure is an ensign. Other grades apply the gold cuff-braid patterns from PDF 65. Badge appears on the wearer’s left chest.'},
 {id:'female-duty',kind:'uniform',category:'uniforms',title:'Duty uniform / female',sub:'Officers and ensigns.',page:70,to:'01:03:14',codes:['SF17','SF32','SF25','SF03'],note:'Fitted short duty tunic with black collar and boots. The historical “Nude” specification describes hosiery, not skin. Ensign is shown without braid (PDF 70); officer grades use PDF 68 and rank patterns from PDF 65. Medical exceptions are outside this study.'}
];
const badgeShape='M310 76 C370 170 424 315 454 505 C396 467 371 379 334 386 C295 389 219 492 145 548 C173 359 230 175 310 76Z';
function device(division){if(division==='sciences')return '<ellipse cx="301" cy="292" rx="37" ry="49" transform="rotate(-40 301 292)" fill="none" stroke="currentColor" stroke-width="13"/><ellipse cx="301" cy="292" rx="58" ry="17" transform="rotate(-40 301 292)" fill="none" stroke="currentColor" stroke-width="10"/>';if(division==='engineering')return '<path d="M270 248L324 232L351 263L341 303L318 320L332 353L304 342L294 309L269 302L254 274Z M281 263L276 280L290 292L315 295L327 281L325 264L306 253Z" fill-rule="evenodd"/>';return '<path d="M302 164L319 276L355 286L320 303L328 343L301 314L275 347L281 304L248 286L281 276Z"/>';}
export function badgeArt(division,p,prefix){return `<defs><linearGradient id="${prefix}-metal" x1="0" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".48"/><stop offset=".4" stop-color="#fff" stop-opacity="0"/><stop offset=".68" stop-color="#000" stop-opacity=".16"/><stop offset=".87" stop-color="#fff" stop-opacity=".3"/><stop offset="1" stop-color="#000" stop-opacity=".12"/></linearGradient><pattern id="${prefix}-thread" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 0L5 5" stroke="#fff" stroke-opacity=".13" stroke-width="1"/></pattern></defs><g transform="translate(0 30)"><path d="${badgeShape}" fill="${p.SF03}" stroke="${p.SF32}" stroke-width="13" stroke-linejoin="round"/><path d="${badgeShape}" fill="url(#${prefix}-metal)"/><path d="${badgeShape}" fill="url(#${prefix}-thread)"/><g fill="${p.SF32}" color="${p.SF32}">${device(division)}</g><path d="${badgeShape}" fill="none" stroke="${p.SF32}" stroke-width="9" stroke-linejoin="round"/></g>`;}
function uniformArt(female,division,rank,back,p,prefix){
 const colour=p[divisions[division].code],black=p.SF32;
 const body=female?'M253 116 Q227 126 206 139 L173 283 L156 401 L193 409 L224 296 L237 231 Q250 280 241 313 L222 410 Q296 434 376 410 L355 313 Q346 280 362 231 L375 296 L406 409 L443 401 L426 283 L393 139 Q371 126 348 116 Q300 133 253 116Z':'M251 115 L207 133 L180 282 L161 400 L201 409 L230 279 L240 220 L235 355 Q300 369 365 355 L360 220 L370 279 L399 409 L439 400 L420 282 L393 133 L349 115 Q300 130 251 115Z';
 const collar=female?'M253 116 Q284 153 339 125 L348 116 Q314 171 256 143 L247 128Z':'M251 115 L298 140 L349 115 L348 129 L299 156 L252 130Z';
 const stripes=ranks[rank].map((full,i)=>`<path d="M${female?164:169} ${383-i*10}l35 8 M${female?401:396} ${391-i*10}l35 -8" stroke="${p.SF03}" stroke-width="5" ${full?'':'stroke-dasharray="8 4"'}/>`).join('');
 return `<defs><linearGradient id="${prefix}-cloth"><stop stop-color="#000" stop-opacity=".2"/><stop offset=".22" stop-color="#fff" stop-opacity=".13"/><stop offset=".47" stop-color="#fff" stop-opacity="0"/><stop offset=".72" stop-color="#000" stop-opacity=".08"/><stop offset="1" stop-color="#000" stop-opacity=".3"/></linearGradient><pattern id="${prefix}-weave" width="3" height="3" patternUnits="userSpaceOnUse"><path d="M0 0H3" stroke="#fff" stroke-opacity=".035"/></pattern></defs>
 <ellipse cx="300" cy="654" rx="122" ry="10" fill="#202321" opacity=".08"/>
 <path d="M272 109V79 Q300 66 329 79V109L349 119Q301 139 251 119Z" fill="#ddd9cf" stroke="#aaa69a" stroke-width="1.5"/>
 ${female?`<path d="M246 405L250 537L284 537L297 434L311 537L345 537L354 405Z" fill="${p.SF25}" stroke="#685b50" stroke-width="1.5"/>`:`<path d="M239 347L244 540L283 540L300 412L315 540L355 540L361 347Z" fill="${black}" stroke="#111" stroke-width="1.5"/><path d="M257 376L262 510M342 376L335 510M300 375V412" fill="none" stroke="#fff" stroke-opacity=".12" stroke-width="2"/>`}
 <path d="M248 518L285 518L283 611Q286 627 279 642L216 643Q211 631 237 614Z M312 518L349 518L361 614Q389 631 383 643L321 642Q313 627 316 611Z" fill="${black}" stroke="#111" stroke-width="2"/>
 <path d="M258 530L253 608L235 625M323 530L328 609L346 627" fill="none" stroke="#fff" stroke-opacity=".16" stroke-width="3"/>
 <path d="${body}" fill="${colour}" stroke="#29251f" stroke-width="2"/>
 <path d="${body}" fill="url(#${prefix}-cloth)"/><path d="${body}" fill="url(#${prefix}-weave)"/>
 <path d="${back?(female?'M253 116Q298 133 348 116L348 127Q301 143 253 127Z':'M251 115Q300 128 349 115V126Q300 140 251 126Z'):collar}" fill="${black}"/>
 <g fill="none" stroke="#000" stroke-opacity=".16" stroke-width="2"><path d="M213 149Q253 163 240 220M387 149Q349 163 360 220M221 277L204 354M379 277L398 354M252 259L249 313M347 259L353 313"/><path d="${female?'M231 403Q300 425 367 403':'M243 348Q300 360 358 348'}"/></g>
 ${back?'<path d="M299 146V343" fill="none" stroke="#000" stroke-opacity=".12"/>':`<g transform="translate(310 149) scale(.07)">${badgeArt(division,p,prefix+'-badge')}</g>`}
 ${stripes}<path d="M165 395l35 8M399 403l35 -8" fill="none" stroke="#000" stroke-opacity=".3" stroke-width="2"/>`;
}
let svgSerial=0;
export function artwork(item,{palette=displayPalette,division=item.division|| (item.id==='female-duty'?'sciences':'command'),rank='ensign',back=false}={}){const prefix=`cp${++svgSerial}`;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 700" role="img" aria-label="${item.title}${item.kind==='uniform'?`, ${divisions[division].name}, ${titleCase(rank)}, ${back?'back':'front'}`:''}" class="colour-art"><title>${item.title} — colour reconstruction from the Star Fleet Technical Manual</title>${item.kind==='uniform'?uniformArt(item.id==='female-duty',division,rank,back,palette,prefix):item.kind==='badge'?badgeArt(item.division,palette,prefix):flagArt(item.kind,palette,prefix)}</svg>`;}
const sourceUrl=p=>`assets/colours/page-${p}.webp`;
const swatches=(codes,p)=>codes.map(code=>`<div class="colour-spec"><i style="background:${p[code]}"></i><span>${names[code]}<small>${code}UC</small></span></div>`).join('');
export function renderColours(main,path){
 let alive=true,scan=null,mode='rendered',category='all',division='command',rank='ensign',back=false;
 const item=plates.find(x=>x.id===path.split('/')[2]);if(item?.id==='female-duty')division='sciences';
 const folio=`<div class="folio"><span><a href="#/">COMMAND SECTION</a> / <a href="#/colours">COLOUR PLATES</a></span><span>STAR FLEET SPECIFICATION / SF–UC</span></div>`;
 const modeControl=`<label class="colour-mode">DISPLAY <select id="colour-mode"><option value="rendered">Named-colour reconstruction</option><option value="scan" disabled>Scan samples · loading</option></select></label>`;
 const method=`<aside class="colour-method"><strong>Reading the colour specification</strong><p>The manual assigns names and SF codes, not RGB values. These drawings follow those assignments; screen hues, shading and materials are reconstructions. The scan’s colour chart is visibly distorted—several different dark colours have clipped to black. “Scan samples” reproduces sampled swatches for comparison, not calibrated physical colour.</p><a href="${sourceUrl(49)}" target="_blank" rel="noopener">View the colour table · PDF 49 / TO 00:10:10 ↗</a></aside>`;
 if(!item){
 main.innerHTML=folio+`<section class="colour-heading"><div><span class="eyebrow">02 / Heraldry & dress</span><h1>The manual,<br>in colour.</h1><p class="intro">Silver stars on a red banner. Gold division insignia. Tenne, Ultramarine and red duty tunics. Follow the colour codes hidden in the black-and-white sheets.</p></div><div class="colour-hero">${artwork(plates[3])}<span>SF03UC · GOLD<br>SF32UC · BLACK</span></div></section><div class="colour-toolbar"><div class="colour-filters" aria-label="Filter colour plates">${['all','flags','insignia','uniforms'].map(c=>`<button data-category="${c}" aria-pressed="${c==='all'}">${titleCase(c)}</button>`).join('')}</div>${modeControl}</div><div id="colour-status" class="colour-status" role="status">8 studies / named-colour reconstructions</div><div id="colour-grid" class="colour-grid"></div>${method}`;
 function gallery(){const list=plates.filter(x=>category==='all'||x.category===category),p=palette();main.querySelector('#colour-grid').innerHTML=list.map((x,i)=>`<a href="#/colours/${x.id}" class="colour-card"><div class="colour-card-art">${artwork(x,{palette:p})}<span class="colour-plate-no">${String(plates.indexOf(x)+1).padStart(2,'0')} / ${x.category.toUpperCase()}</span></div><div class="colour-card-copy"><h2>${x.title} <span>↗</span></h2><p>${x.sub}</p><div class="colour-mini">${x.codes.map(c=>`<i title="${names[c]} · ${c}UC" style="background:${p[c]}"></i>`).join('')}<span>TO ${x.to}</span></div></div></a>`).join('');main.querySelector('#colour-status').textContent=`${list.length} studies / ${mode==='scan'?'uncalibrated scan samples':'named-colour reconstructions'}`;}
 main.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;main.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));gallery();});
 main.querySelector('#colour-mode').onchange=e=>{mode=e.target.value;gallery();main.querySelector('.colour-hero').innerHTML=artwork(plates[3],{palette:palette()})+'<span>SF03UC · GOLD<br>SF32UC · BLACK</span>';};gallery();
 }else{
 main.innerHTML=folio+`<div class="sheet-title"><div><span class="eyebrow">${item.category} / colour study</span><h1>${item.title}</h1></div><a class="btn outline" href="#/colours">All colour plates ↗</a></div><div class="colour-study"><section class="colour-stage"><div class="colour-toolbar">${modeControl}<button id="colour-download" class="icon-btn">Save SVG ↓</button></div><div id="colour-large"></div><div class="colour-stage-caption"><span id="render-caption">NAMED-COLOUR RECONSTRUCTION</span><span>VECTOR STUDY / NOT A 3D PRINT FILE</span></div></section><aside class="colour-particulars"><span class="eyebrow">The specification</span><p>${item.note}</p>${item.kind==='uniform'?`<div class="uniform-controls"><label>DIVISION<select id="uniform-division">${Object.entries(divisions).map(([id,d])=>`<option value="${id}" ${division===id?'selected':''}>${d.name}</option>`).join('')}</select></label><label>GRADE<select id="uniform-rank">${Object.keys(ranks).map(id=>`<option value="${id}">${titleCase(id)}</option>`).join('')}</select></label><button class="btn outline" id="uniform-back" aria-pressed="false">Show back view ↻</button></div>`:''}<div id="colour-specs"></div><div class="colour-source-links" id="colour-source-links"></div></aside></div><details class="colour-source"><summary>Compare with the original manual sheet</summary><img id="colour-source-image" src="${sourceUrl(item.page)}" alt="Original source drawing, PDF ${item.page}" loading="lazy"></details>${method}<div class="pagination"><a href="#/colours/${plates[(plates.indexOf(item)+plates.length-1)%plates.length].id}">← Previous plate</a><a href="#/colours">All colour plates</a><a href="#/colours/${plates[(plates.indexOf(item)+1)%plates.length].id}">Next plate →</a></div>`;
 function update(){const p=palette(),codes=item.kind==='uniform'?[divisions[division].code,'SF32',...(item.id==='female-duty'?['SF25']:[]),'SF03']:item.codes;main.querySelector('#colour-large').innerHTML=artwork(item,{palette:p,division,rank,back});main.querySelector('#colour-specs').innerHTML=swatches(codes,p);main.querySelector('#render-caption').textContent=mode==='scan'?'UNCALIBRATED SCAN-SAMPLE COLOURS':'NAMED-COLOUR RECONSTRUCTION';const page=item.id==='female-duty'&&rank!=='ensign'?68:item.page;const to=page===68?'01:03:12':item.to;main.querySelector('#colour-source-links').innerHTML=`<a href="${sourceUrl(page)}" target="_blank" rel="noopener">Source: PDF ${page} / TO ${to} ↗</a>${item.kind==='uniform'?`<a href="${sourceUrl(65)}" target="_blank" rel="noopener">Insignia & braid: PDF 65 ↗</a>`:''}<a href="${sourceUrl(49)}" target="_blank" rel="noopener">Colour specification: PDF 49 ↗</a>`;main.querySelector('#colour-source-image').src=sourceUrl(page);main.querySelector('#colour-source-image').alt=`Original manual source, PDF ${page}`;}
 main.querySelector('#colour-mode').onchange=e=>{mode=e.target.value;update();};
 if(item.kind==='uniform'){main.querySelector('#uniform-division').onchange=e=>{division=e.target.value;update();};main.querySelector('#uniform-rank').onchange=e=>{rank=e.target.value;update();};main.querySelector('#uniform-back').onclick=e=>{back=!back;e.currentTarget.setAttribute('aria-pressed',String(back));e.currentTarget.textContent=back?'Show front view ↻':'Show back view ↻';update();};}
 main.querySelector('#colour-download').onclick=()=>{const svg=main.querySelector('#colour-large svg').outerHTML;const url=URL.createObjectURL(new Blob(['<?xml version="1.0" encoding="UTF-8"?>\n'+svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download=`${item.id}-${item.kind==='uniform'?division+'-'+rank+'-'+(back?'back':'front')+'-':''}${mode}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};update();
 }
 function palette(){return mode==='scan'&&scan?Object.fromEntries(Object.entries(scan.colours).map(([k,v])=>[k,v.hex])):displayPalette;}
 fetch('assets/colours/palette-scan.json').then(r=>{if(!r.ok)throw Error('Palette unavailable');return r.json();}).then(data=>{if(!alive)return;scan=data;const option=main.querySelector('#colour-mode option[value="scan"]');option.disabled=false;option.textContent='Scan samples · uncalibrated';}).catch(()=>{if(alive)main.querySelector('#colour-mode option[value="scan"]').textContent='Scan samples unavailable';});
 return ()=>{alive=false;};
}
